import React, { useEffect, useState } from 'react';
import Container from 'react-bootstrap/Container';
import Row from 'react-bootstrap/Row';
import Col from 'react-bootstrap/Col';
import { Link, useLocation } from 'react-router-dom';
import { Table } from 'react-bootstrap';
import CompanyDetails from '../../../components/Atom/CompanyDetails';
import moment from 'moment';
import { isArray } from 'lodash';
import { numberToRupeesWords } from '../../../utils/AllFunction';
import { usePageTitle } from '../../../hooks';

function Index() {

    usePageTitle({
        title: 'Salary',
        breadCrumbItems: [
            {
                path: '/salary/staff-advance',
                label: 'Salary Advance',
            },
            {
                path: '/payment-receipt-report',
                label: 'Payment Receipt Report',
                active: true,
            },
        ],
    });

    const today = new Date().toLocaleDateString();

    const { state } = useLocation();

    const [stateVal, setStateVal] = useState({ paidAmount: 0 })

    useEffect(() => {
        if (state != undefined && state != null) {
            setStateVal(state || {});
        }
    }, [state])

    const staffLedger = {
        ledger: {
            paidDate: `${stateVal[0]?.paidDate}`,
            paidAmount: `${stateVal[0]?.paidAmount}`,
            staffAdvanceId: `${stateVal[0]?.staffAdvanceId}`,
            staffDepartment: `${stateVal[0]?.departmentName}`,
            staffdesignation: `${stateVal[0]?.designationName}`,
            throughName: `${stateVal[0]?.throughName}`,
            accountName: `${stateVal[0]?.accountName}`,
            description: `${stateVal[0]?.description}`,
            staffCode: `${stateVal[0]?.staffCode}`,
            staffPhnNo: `${stateVal[0]?.contactNo}`,
            table: (isArray(stateVal) ? stateVal : []).map((item, i) => ({
                ["s.no"]: i + 1,
                date: moment(item?.date).format('DD-MM-YYYY'),
                credit: Number(item?.credit),
                debit: Number(item?.debit),
            }))
        },
    };

    const footerFields = [
        ['Authorised Sign', '', 'Receiver"s Sign'],
        ['', '', ''],
    ];

    let snoCounter = 1;

    const paginatedData = [];
    let tempTable = [...staffLedger.ledger.table];

    // First page
    paginatedData.push(tempTable.splice(0, 13));

    // Middle pages
    while (tempTable.length > 20) {
        paginatedData.push(tempTable.splice(0, 20));
    }

    // Last page
    if (tempTable.length > 0) {
        paginatedData.push(tempTable);
    }

    const totals = staffLedger.ledger.table.reduce(
        (acc, row) => ({
            credit: acc.credit + Number(row.credit || 0),
            debit: acc.debit + Number(row.debit || 0),
        }),
        { credit: 0, debit: 0 }
    );

    return (
        <Container className="letter-container my-4 p-4 bg-white" style={{ maxWidth: '800px' }}>
            {paginatedData.map((pageData, pageIndex) => (
                <div key={pageIndex} className="page-container" style={{ marginBottom: '10px' }}>
                    {pageIndex === 0 && (
                        <>
                            <Row className="mt-1 mb-1">

                                {/* <Row className="justify-between ">
                                    <Col className="text-black" style={{ fontSize: '16px', alignSelf: 'center'  }} xs={4}>
                                        <Row >
                                            
                                        </Row>
                                        
                                    </Col>
                                    {/* <Col className="text-black" style={{ fontSize: '16px', alignSelf: 'center' }} xs={8}>
                                        <Row>
                                            <h3 style={{ color: 'black', marginTop: '10px' }}>K3 WOMEN FOUNDATION</h3>
                                            
                                        </Row>                                        
                                        
                                    </Col> 
                                    
                                </Row> */}

                                <CompanyDetails
                                    fontSize="12px"
                                    imgOnly={false}
                                    imgSize="200px"
                                    classStyle="d-flex justify-content-center flex-column align-items-center"
                                />


                                <Row style={{ fontSize: '16px', textAlign: 'center' }}>
                                    <Col xs={12}>
                                        <h3 style={{ color: 'black', marginTop: '15px' }}>Receipt Voucher</h3>
                                    </Col>

                                </Row>

                            </Row>
                        </>
                    )}

                    <Table style={{ borderColor: '#fff', marginTop: '5px' }}>
                        <thead>
                            <tr>
                                <th style={{ color: 'black', textAlign: 'left' }}>Voucher No : {stateVal.staffAdvanceId} </th>
                                <th style={{ color: 'black', textAlign: 'right' }}>Voucher Date :  {moment(stateVal.paidDate).format("DD-MM-YYYY")}</th>

                            </tr>
                        </thead>
                    </Table>

                    {/* Table Data */}
                    <Table hover style={{ borderCollapse: 'collapse', border: 'none', marginTop: '-25px' }}>
                        <thead style={{ backgroundColor: '#f2f2f2' }}>
                            <tr>
                                <th style={{ color: 'black', textAlign: 'left', border: 'none' }}>Particulars</th>
                                <th style={{ color: 'black', textAlign: 'right', border: 'none' }}>Amount</th>
                            </tr>
                        </thead>
                        <tbody>
                            <>
                                <tr style={{ border: 'none' }}>
                                    <td style={{ textAlign: 'left', border: 'none' }}>
                                        <h4 style={{ color: 'black', marginTop: '10px' }}> Account : </h4> {stateVal.accountName}
                                    </td>
                                    <td style={{ fontSize: '14px', color: 'black', textAlign: 'right', border: 'none' }}>
                                        {stateVal.paidAmount}
                                    </td>
                                </tr>
                                <tr style={{ border: 'none' }}>
                                    <td style={{ textAlign: 'left', border: 'none' }}>
                                        <h4 style={{ color: 'black', marginTop: '10px' }}> Through : </h4> {stateVal.throughName}
                                    </td>
                                    <td style={{ fontSize: '14px', color: 'black', textAlign: 'left', border: 'none' }}></td>
                                </tr>
                                <tr style={{ border: 'none' }}>
                                    <td style={{ textAlign: 'left', border: 'none' }}>
                                        <h4 style={{ color: 'black', marginTop: '10px' }}> On Account of :</h4> {stateVal.description}
                                    </td>
                                    <td style={{ fontSize: '14px', color: 'black', textAlign: 'left', border: 'none' }}></td>
                                </tr>
                                <tr style={{ border: 'none' }}>
                                    <td style={{ textAlign: 'left', border: 'none' }}>
                                        <h4 style={{ color: 'black', marginTop: '10px' }}> Amount (in words) : </h4>{numberToRupeesWords(stateVal.paidAmount)}
                                    </td>
                                    <td style={{ fontSize: '14px', color: 'black', textAlign: 'right', border: 'none' }}></td>
                                </tr>
                                <tr style={{ border: 'none', backgroundColor: '#f2f2f2' }} >
                                    <td style={{ textAlign: 'right', fontWeight: 'bold', color: 'black', border: 'none' }}>
                                        Total
                                    </td>
                                    <td style={{ textAlign: 'right', fontWeight: 'bold', color: 'black', border: 'none' }}>
                                        {stateVal.paidAmount}
                                    </td>
                                </tr>
                            </>
                        </tbody>
                    </Table>

                    {/* Footer Section (only on the last page) */}
                    {pageIndex === paginatedData.length - 1 && (
                        <div style={{ marginTop: '40px', padding: '10px' }}>
                            {footerFields.map((row, rowIndex) => (
                                <Row key={rowIndex} className="justify-between mb-2">
                                    {row.map((col, colIndex) => (
                                        <Col
                                            key={colIndex}
                                            className="text-center"
                                            style={{
                                                fontSize: '16px',
                                                color: 'black',
                                                fontWeight: 'bold',
                                                flex: 1,
                                                marginTop: "20px"
                                            }}>
                                            {col && <strong>{col}</strong>}
                                        </Col>
                                    ))}
                                </Row>
                            ))}
                        </div>
                    )}

                    {/* Page Break */}
                    {pageIndex < paginatedData.length - 1 && <div className="page-break"></div>}
                </div>
            ))}

            <Row className="d-print-none mt-4">
                <Col className="text-end">
                    <Link
                        to="#"
                        className="btn btn-dark me-1"
                        onClick={(e) => {
                            window.print();
                        }}>
                        <i className="fa fa-print"></i>
                    </Link>
                    <Link to="#" className="btn btn-success me-1">
                        <i className="fa fa-download"></i> Download as PDF
                    </Link>
                </Col>
            </Row>

            <style>
                {`
                    @media print {
                        .page-break { 
                            page-break-before: always; 
                        }
                    }
                `}
            </style>
        </Container>
    );
}

export default Index;
